import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import { ref, nextTick } from 'vue';
import axios from 'axios';
import { ElMessage, ElMessageBox } from 'element-plus';
import DockerContainers from '@/components/Container/DockerContainers.vue';

// 状态变量

export default {
  __name: 'FirewallRuleManager',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const containerName = ref('');
    const chain = ref('');
    const rules = ref([]);
    const headers = ref([]);
    const loading = ref(false);
    const activeTab = ref('view');
    const containers = ref([]);
    const containersRef = ref(null);

    // 打开弹窗初始化
    const openDialog = async () => {
      dialogVisible.value = true;
      containerName.value = '';
      chain.value = '';
      activeTab.value = 'view';
      rules.value = [];
      headers.value = [];
      await nextTick();
      if (containersRef.value) {
        await containersRef.value.fetchContainers();
        containers.value = containersRef.value.containers || [];
      }
    };
    __expose({
      openDialog
    });

    // 获取防火墙规则
    const handleViewRules = async () => {
      if (!containerName.value || !chain.value) {
        ElMessage.warning('请选择容器和链名称');
        return;
      }
      loading.value = true;
      try {
        const response = await axios.get('http://localhost:8081/firewall/list', {
          params: {
            containerName: containerName.value,
            chain: chain.value
          }
        });
        const lines = response.data.split('\n').map(line => line.trim()).filter(line => line.length > 0);
        if (lines.length < 2) {
          rules.value = [];
          headers.value = [];
          return;
        }
        headers.value = lines[1].split(/\s+/);
        rules.value = lines.slice(2).map(line => {
          const parts = line.split(/\s+/);
          const obj = {};
          parts.forEach((p, idx) => {
            obj[`field${idx}`] = p;
          });
          return obj;
        });
      } catch (err) {
        ElMessage.error(`获取规则失败：${err?.response?.data || err.message}`);
      } finally {
        loading.value = false;
      }
    };

    // 删除规则
    const handleDelete = async index => {
      try {
        await ElMessageBox.confirm(`确定要删除序号为 ${index} 的规则吗？`, '确认删除', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          confirmButtonClass: 'el-button--danger',
          cancelButtonClass: 'el-button--default',
          distinguishCancelAndClose: true,
          type: 'warning',
          customClass: 'confirm-box-left'
        });
        await axios.delete('http://localhost:8081/firewall/deleteByIndex', {
          params: {
            containerName: containerName.value,
            chain: chain.value,
            index: index
          }
        });
        ElMessage.success(`已删除规则 #${index}`);
        await handleViewRules();
      } catch (err) {
        if (err !== 'cancel') {
          ElMessage.error(`删除失败：${err?.response?.data || err.message}`);
        }
      }
    };
    const __returned__ = {
      dialogVisible,
      containerName,
      chain,
      rules,
      headers,
      loading,
      activeTab,
      containers,
      containersRef,
      openDialog,
      handleViewRules,
      handleDelete,
      ref,
      nextTick,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      get ElMessageBox() {
        return ElMessageBox;
      },
      DockerContainers
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
